{"sql":"-- Verify trigger fired and report was created
BEGIN;

-- Query salary alerts
SELECT * FROM employees.salary_alerts ORDER BY alert_date DESC, employee_id LIMIT 10;

-- Fetch the generated report
SELECT mr.*
FROM employees.monthly_reports mr
JOIN pg_temp._last_report_id l ON l.id = mr.report_id;

-- 6) Performance Indexes
CREATE INDEX IF NOT EXISTS idx_salary_alerts_status ON employees.salary_alerts(status);
CREATE INDEX IF NOT EXISTS idx_monthly_reports_report_date_department_count ON employees.monthly_reports(report_date, department_count);

COMMIT;"}

{"sql":"BEGIN;

-- Show salary alerts
SELECT * FROM employees.salary_alerts ORDER BY alert_date DESC, employee_id LIMIT 10;

-- Fetch the generated January 2024 report
SELECT *
FROM employees.monthly_reports
WHERE report_date = DATE '2024-01-01'
ORDER BY report_id DESC
LIMIT 1;

-- Create performance indexes
CREATE INDEX IF NOT EXISTS idx_salary_alerts_status ON employees.salary_alerts(status);
CREATE INDEX IF NOT EXISTS idx_monthly_reports_report_date_department_count ON employees.monthly_reports(report_date, department_count);

COMMIT;"}
